(function () {
  "use strict";

  const STORAGE_KEY = "habitTracker.v1";
  const DAY_NAMES = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

  const form = document.getElementById("add-form");
  const input = document.getElementById("habit-input");
  const headRow = document.getElementById("head-row");
  const body = document.getElementById("habit-body");
  const emptyMsg = document.getElementById("empty-msg");
  const weekLabel = document.getElementById("week-label");
  const table = document.getElementById("habit-table");

  // ---- Date helpers (local time, not UTC) ----

  /** Format a Date as YYYY-MM-DD using local time. */
  function toKey(date) {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, "0");
    const d = String(date.getDate()).padStart(2, "0");
    return `${y}-${m}-${d}`;
  }

  /** Return the 7 dates (Mon..Sun) of the week containing `ref`. */
  function getWeekDates(ref) {
    const start = new Date(ref.getFullYear(), ref.getMonth(), ref.getDate());
    const offset = (start.getDay() + 6) % 7; // Monday = 0
    start.setDate(start.getDate() - offset);
    return Array.from({ length: 7 }, (_, i) => {
      const d = new Date(start);
      d.setDate(start.getDate() + i);
      return d;
    });
  }

  // ---- Storage ----

  function load() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      const data = raw ? JSON.parse(raw) : [];
      if (!Array.isArray(data)) return [];
      return data
        .filter((h) => h && typeof h.id === "string" && typeof h.name === "string")
        .map((h) => ({
          id: h.id,
          name: h.name,
          done: h.done && typeof h.done === "object" ? h.done : {},
        }));
    } catch (err) {
      console.warn("Could not read saved habits:", err);
      return [];
    }
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(habits));
    } catch (err) {
      console.warn("Could not save habits:", err);
    }
  }

  function makeId() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  // ---- State ----

  let habits = load();
  let weekDates = [];
  let todayKey = "";

  // ---- Rendering ----

  function renderHeader() {
    headRow.querySelectorAll(".day-head").forEach((th) => th.remove());
    const countHead = headRow.querySelector(".count-col");

    weekDates.forEach((date, i) => {
      const th = document.createElement("th");
      th.scope = "col";
      th.className = "day-head";
      const key = toKey(date);
      if (key === todayKey) th.classList.add("today");
      th.innerHTML = `${DAY_NAMES[i]}<span class="day-date">${date.getDate()}/${date.getMonth() + 1}</span>`;
      headRow.insertBefore(th, countHead);
    });

    const fmt = { day: "numeric", month: "short" };
    const first = weekDates[0].toLocaleDateString(undefined, fmt);
    const last = weekDates[6].toLocaleDateString(undefined, { ...fmt, year: "numeric" });
    weekLabel.textContent = `Week of ${first} – ${last}`;
  }

  function renderBody() {
    body.innerHTML = "";
    const keys = weekDates.map(toKey);

    habits.forEach((habit) => {
      const tr = document.createElement("tr");
      tr.dataset.id = habit.id;

      const nameTd = document.createElement("td");
      nameTd.className = "habit-name";
      nameTd.textContent = habit.name;
      tr.appendChild(nameTd);

      keys.forEach((key, i) => {
        const td = document.createElement("td");
        if (key === todayKey) td.classList.add("today");
        const cb = document.createElement("input");
        cb.type = "checkbox";
        cb.className = "day-check";
        cb.dataset.date = key;
        cb.checked = Boolean(habit.done[key]);
        cb.setAttribute("aria-label", `${habit.name} on ${DAY_NAMES[i]} ${key}`);
        td.appendChild(cb);
        tr.appendChild(td);
      });

      const countTd = document.createElement("td");
      countTd.className = "count-cell";
      countTd.textContent = `${countWeek(habit, keys)}/7`;
      tr.appendChild(countTd);

      const actionTd = document.createElement("td");
      const del = document.createElement("button");
      del.type = "button";
      del.className = "delete-btn";
      del.textContent = "✕";
      del.title = "Delete habit";
      del.setAttribute("aria-label", `Delete ${habit.name}`);
      actionTd.appendChild(del);
      tr.appendChild(actionTd);

      body.appendChild(tr);
    });

    const empty = habits.length === 0;
    emptyMsg.hidden = !empty;
    table.hidden = empty;
  }

  function countWeek(habit, keys) {
    return keys.reduce((n, k) => n + (habit.done[k] ? 1 : 0), 0);
  }

  function render() {
    const now = new Date();
    todayKey = toKey(now);
    weekDates = getWeekDates(now);
    renderHeader();
    renderBody();
  }

  // ---- Events ----

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const name = input.value.trim();
    if (!name) return;
    habits.push({ id: makeId(), name, done: {} });
    save();
    input.value = "";
    renderBody();
    input.focus();
  });

  body.addEventListener("change", (e) => {
    const cb = e.target;
    if (!cb.classList.contains("day-check")) return;
    const row = cb.closest("tr");
    const habit = habits.find((h) => h.id === row.dataset.id);
    if (!habit) return;

    if (cb.checked) habit.done[cb.dataset.date] = true;
    else delete habit.done[cb.dataset.date];
    save();

    row.querySelector(".count-cell").textContent =
      `${countWeek(habit, weekDates.map(toKey))}/7`;
  });

  body.addEventListener("click", (e) => {
    const btn = e.target.closest(".delete-btn");
    if (!btn) return;
    const row = btn.closest("tr");
    const habit = habits.find((h) => h.id === row.dataset.id);
    if (!habit) return;
    if (!confirm(`Delete "${habit.name}"? This removes all its history.`)) return;
    habits = habits.filter((h) => h.id !== habit.id);
    save();
    renderBody();
  });

  // Keep in sync if another tab changes the data.
  window.addEventListener("storage", (e) => {
    if (e.key !== STORAGE_KEY) return;
    habits = load();
    renderBody();
  });

  // Re-render when the day (and possibly the week) rolls over while the page is open.
  document.addEventListener("visibilitychange", () => {
    if (!document.hidden && toKey(new Date()) !== todayKey) render();
  });
  setInterval(() => {
    if (toKey(new Date()) !== todayKey) render();
  }, 60 * 1000);

  render();
})();

