      pendingToday = true;
      day.setDate(day.getDate() - 1);
    }
    let count = 0;
    while (habit.done[toKey(day)]) {
      count++;
      day.setDate(day.getDate() - 1);
    }
    return { count, pendingToday: pendingToday && count > 0 };
  }

  function updateRowStats(tr, habit, keys) {
    const { count, pendingToday } = getStreak(habit);
    const streakTd = tr.querySelector(".streak-cell");
    streakTd.classList.toggle("zero", count === 0);
    const dayWord = count === 1 ? "day" : "days";
    streakTd.title = pendingToday
      ? `${count}-${dayWord.replace(/s$/, "")} streak — tick today to keep it going`
      : `${count} ${dayWord} in a row`;
    streakTd.innerHTML = count === 0 ? "0" : `🔥 ${count}`;
    if (pendingToday) {
      const note = document.createElement("span");
      note.className = "pending";
      note.textContent = "tick today";
      streakTd.appendChild(note);
    }

    const done = countWeek(habit, keys);
    const countTd = tr.querySelector(".count-cell");
    countTd.innerHTML = "";
    countTd.append(`${done}/7`);
    const pct = document.createElement("span");
    pct.className = "pct";
    pct.textContent = `${percent(done, 7)}%`;
    countTd.appendChild(pct);
  }

  /** Overall completion for the week: all ticks across all habits ÷ (habits × 7). */
  function renderSummary() {
    if (habits.length === 0) {
      summary.hidden = true;
      return;
    }
    summary.hidden = false;

    const keys = weekDates.map(toKey);
    const total = habits.length * 7;
    const done = habits.reduce((n, h) => n + countWeek(h, keys), 0);
    const pct = percent(done, total);

    summaryPct.textContent = `${pct}%`;
    summaryFill.style.width = `${pct}%`;
    summaryBar.setAttribute("aria-valuenow", String(pct));

    let best = null;
    habits.forEach((h) => {
      const s = getStreak(h).count;
      if (s > 0 && (!best || s > best.count)) best = { name: h.name, count: s };
    });

    let detail = `${done} of ${total} check-ins done`;
    if (best) {
      detail += ` · Longest current streak: ${best.name} (${best.count} ${best.count === 1 ? "day" : "days"})`;
    }
    summaryDetail.textContent = detail;
  }

  function render() {
    const now = new Date();
    todayKey = toKey(now);
    weekDates = getWeekDates(now);
    renderHeader();
    renderBody();
  }

  // ---- Events ----

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const name = input.value.trim();
    if (!name) return;
    habits.push({ id: makeId(), name, done: {} });
    save();
    input.value = "";
    renderBody();
    input.focus();
  });

  body.addEventListener("change", (e) => {
    const cb = e.target;
    if (!cb.classList.contains("day-check")) return;
    const row = cb.closest("tr");
    const habit = habits.find((h) => h.id === row.dataset.id);
    if (!habit) return;

    if (cb.checked) habit.done[cb.dataset.date] = true;
    else delete habit.done[cb.dataset.date];
    save();

    row.querySelector(".count-cell").textContent =
      `${countWeek(habit, weekDates.map(toKey))}/7`;
  });

  body.addEventListener("click", (e) => {
    const btn = e.target.closest(".delete-btn");
    if (!btn) return;
    const row = btn.closest("tr");
    const habit = habits.find((h) => h.id === row.dataset.id);
    if (!habit) return;
    if (!confirm(`Delete "${habit.name}"? This removes all its history.`)) return;
    habits = habits.filter((h) => h.id !== habit.id);
    save();
    renderBody();
  });

  // Keep in sync if another tab changes the data.
  window.addEventListener("storage", (e) => {
    if (e.key !== STORAGE_KEY) return;
    habits = load();
    renderBody();
  });

  // Re-render when the day (and possibly the week) rolls over while the page is open.
  document.addEventListener("visibilitychange", () => {
    if (!document.hidden && toKey(new Date()) !== todayKey) render();
  });
  setInterval(() => {
    if (toKey(new Date()) !== todayKey) render();
  }, 60 * 1000);

  render();
})();

