// Throwaway harness: minimal DOM stub so app.js can run under Node.
const fs = require("fs");
const path = require("path");
const vm = require("vm");

class El {
  constructor(tag, id) {
    this.tag = tag; this.id = id; this.children = []; this.parent = null;
    this.attrs = {}; this.dataset = {}; this.style = {}; this.listeners = {};
    this._text = ""; this.hidden = false; this.checked = false; this.title = "";
    const self = this;
    this.cls = new Set();
    this.classList = {
      add: (c) => self.cls.add(c),
      contains: (c) => self.cls.has(c),
      toggle: (c, on) => (on ? self.cls.add(c) : self.cls.delete(c)),
    };
  }
  set className(v) { this.cls = new Set(v.split(/\s+/).filter(Boolean)); }
  get className() { return [...this.cls].join(" "); }
  set textContent(v) { this.children = []; this._text = String(v); }
  get textContent() { return this._text + this.children.map((c) => c.textContent).join(""); }
  set innerHTML(v) { this.children = []; this._text = String(v).replace(/<[^>]+>/g, " "); }
  appendChild(c) { c.parent = this; this.children.push(c); return c; }
  append(s) { const t = new El("#text"); t._text = String(s); this.appendChild(t); }
  insertBefore(c, ref) { c.parent = this; const i = this.children.indexOf(ref); this.children.splice(i < 0 ? this.children.length : i, 0, c); }
  remove() { if (this.parent) this.parent.children = this.parent.children.filter((x) => x !== this); }
  setAttribute(k, v) { this.attrs[k] = v; }
  addEventListener(t, f) { (this.listeners[t] ||= []).push(f); }
  all() { return this.children.flatMap((c) => [c, ...c.all()]); }
  querySelectorAll(sel) { const c = sel.slice(1); return this.all().filter((e) => e.cls.has(c)); }
  querySelector(sel) { return this.querySelectorAll(sel)[0] || null; }
  closest(sel) { let e = this; const c = sel.slice(1); while (e && !(sel === "tr" ? e.tag === "tr" : e.cls.has(c))) e = e.parent; return e; }
  focus() {}
}

const ids = {};
const mk = (id, tag = "div", cls) => { const e = new El(tag, id); if (cls) e.className = cls; ids[id] = e; return e; };
["add-form", "habit-input", "habit-body", "empty-msg", "week-label", "habit-table",
 "summary", "summary-pct", "summary-bar", "summary-fill", "summary-detail"].forEach((i) => mk(i));
const head = mk("head-row", "tr");
["habit-col", "streak-col", "count-col", "action-col"].forEach((c) => head.appendChild(new El("th")).className = c);

// Fixed "today": Sunday 2026-11-22 (week Mon 16 – Sun 22).
const RealDate = Date;
const FIXED = new RealDate(2026, 10, 22, 12, 0, 0).getTime();
class FakeDate extends RealDate { constructor(...a) { a.length ? super(...a) : super(FIXED); } static now() { return FIXED; } }

const store = {};
const seed = [
  // 5 ticked days in a row ending today (spans into previous week: 18..22) -> streak 5, week 5/7
  { id: "a", name: "Read", done: { "2026-11-18": true, "2026-11-19": true, "2026-11-20": true, "2026-11-21": true, "2026-11-22": true } },
  // today not ticked, 3 days ending yesterday (Nov 13 previous week + gap) -> streak 3 pending; week 2/7
  { id: "b", name: "Run", done: { "2026-11-14": true, "2026-11-19": true, "2026-11-20": true, "2026-11-21": true, "2026-11-16": true } },
  // gap yesterday -> streak 0; week 1/7
  { id: "c", name: "Meditate", done: { "2026-11-20": true } },
];
store["habitTracker.v1"] = JSON.stringify(seed);

const ctx = {
  document: { getElementById: (i) => ids[i], addEventListener() {}, hidden: false },
  window: { addEventListener() {} },
  localStorage: { getItem: (k) => store[k] ?? null, setItem: (k, v) => { store[k] = v; } },
  Date: FakeDate, console, setInterval() {}, confirm: () => true, JSON, Math, Array, String, Boolean,
};
vm.createContext(ctx);
vm.runInContext(fs.readFileSync(path.join(__dirname, "..", "app.js"), "utf8"), ctx);

function dump(label) {
  console.log(`--- ${label}`);
  for (const tr of ids["habit-body"].children) {
    const name = tr.querySelector(".habit-name").textContent;
    const s = tr.querySelector(".streak-cell");
    console.log(`${name.padEnd(9)} streak=[${s.textContent.trim()}] zero=${s.cls.has("zero")} week=[${tr.querySelector(".count-cell").textContent}]  title="${s.title}"`);
  }
  console.log(`summary hidden=${ids.summary.hidden} pct=${ids["summary-pct"].textContent} fill=${ids["summary-fill"].style.width} aria=${ids["summary-bar"].attrs["aria-valuenow"]}`);
  console.log(`detail: ${ids["summary-detail"].textContent}`);
}
dump("initial");
console.log("day headers:", head.children.map((c) => c.className).join(","));

// Tick today for Run via change event
const runRow = ids["habit-body"].children[1];
const todayCb = runRow.all().find((e) => e.dataset.date === "2026-11-22");
todayCb.checked = true;
ids["habit-body"].listeners.change[0]({ target: todayCb });
dump("after ticking Run today");

// Untick Read on Thursday 19 (breaks streak to 3)
const readRow = ids["habit-body"].children[0];
const thu = readRow.all().find((e) => e.dataset.date === "2026-11-19");
thu.checked = false;
ids["habit-body"].listeners.change[0]({ target: thu });
dump("after unticking Read Thu 19");

// Delete all
for (const id of ["a", "b", "c"]) {
  const row = ids["habit-body"].children[0];
  ids["habit-body"].listeners.click[0]({ target: row.querySelector(".delete-btn") });
}
console.log("--- after deleting all: summary hidden =", ids.summary.hidden, "table hidden =", ids["habit-table"].hidden);

