// Throwaway harness: minimal DOM stub so app.js can run under Node.
const fs = require("fs");
const path = require("path");
const vm = require("vm");

class El {
  constructor(tag, id) {
    this.tag = tag; this.id = id; this.children = []; this.parent = null;
    this.attrs = {}; this.dataset = {}; this.style = {}; this.listeners = {};
    this._text = ""; this.hidden = false; this.checked = false; this.title = "";
    const self = this;
    this.cls = new Set();
    this.classList = {
      add: (c) => self.cls.add(c),
      contains: (c) => self.cls.has(c),
      toggle: (c, on) => (on ? self.cls.add(c) : self.cls.delete(c)),
    };
  }
  set className(v) { this.cls = new Set(v.split(/\s+/).filter(Boolean)); }
  get className() { return [...this.cls].join(" "); }
  set textContent(v) { this.children = []; this._text = String(v); }
  get textContent() { return this._text + this.children.map((c) => c.textContent).join(""); }
  set innerHTML(v) { this.children = []; this._text = String(v).replace(/<[^>]+>/g, " "); }
  appendChild(c) { c.parent = this; this.children.push(c); return c; }
  append(s) { const t = new El("#text"); t._text = String(s); this.appendChild(t); }
  insertBefore(c, ref) { c.parent = this; const i = this.children.indexOf(ref); this.children.splice(i < 0 ? this.children.length : i, 0, c); }
  remove() { if (this.parent) this.parent.children = this.parent.children.filter((x) => x !== this); }
  setAttribute(k, v) { this.attrs[k] = v; }
  addEventListener(t, f) { (this.listeners[t] ||= []).push(f); }
  all() { return this.children.flatMap((c) => [c, ...c.all()]); }
  querySelectorAll(sel) { const c = sel.slice(1); return this.all().filter((e) => e.cls.has(c)); }
  querySelector(sel) { return this.querySelectorAll(sel)[0] || null; }
  closest(sel) { let e = this; const c = sel.slice(1); while (e && !(sel === "tr" ? e.tag === "tr" : e.cls.has(c))) e = e.parent; return e; }
  focus() {}
}

