1	(function () {
2	  "use strict";
3	
4	  const STORAGE_KEY = "habitTracker.v1";
5	  const DAY_NAMES = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
6	
7	  const form = document.getElementById("add-form");
8	  const input = document.getElementById("habit-input");
9	  const headRow = document.getElementById("head-row");
10	  const body = document.getElementById("habit-body");
11	  const emptyMsg = document.getElementById("empty-msg");
12	  const weekLabel = document.getElementById("week-label");
13	  const table = document.getElementById("habit-table");
14	  const summary = document.getElementById("summary");
15	  const summaryPct = document.getElementById("summary-pct");
16	  const summaryBar = document.getElementById("summary-bar");
17	  const summaryFill = document.getElementById("summary-fill");
18	  const summaryDetail = document.getElementById("summary-detail");
19	
20	  // ---- Date helpers (local time, not UTC) ----
21	
22	  /** Format a Date as YYYY-MM-DD using local time. */
23	  function toKey(date) {
24	    const y = date.getFullYear();
25	    const m = String(date.getMonth() + 1).padStart(2, "0");
26	    const d = String(date.getDate()).padStart(2, "0");
27	    return `${y}-${m}-${d}`;
28	  }
29	
30	  /** Return the 7 dates (Mon..Sun) of the week containing `ref`. */
31	  function getWeekDates(ref) {
32	    const start = new Date(ref.getFullYear(), ref.getMonth(), ref.getDate());
33	    const offset = (start.getDay() + 6) % 7; // Monday = 0
34	    start.setDate(start.getDate() - offset);
35	    return Array.from({ length: 7 }, (_, i) => {
36	      const d = new Date(start);
37	      d.setDate(start.getDate() + i);
38	      return d;
39	    });
40	  }
41	
42	  // ---- Storage ----
43	
44	  function load() {
45	    try {
46	      const raw = localStorage.getItem(STORAGE_KEY);
47	      const data = raw ? JSON.parse(raw) : [];
48	      if (!Array.isArray(data)) return [];
49	      return data
50	        .filter((h) => h && typeof h.id === "string" && typeof h.name === "string")
51	        .map((h) => ({
52	          id: h.id,
53	          name: h.name,
54	          done: h.done && typeof h.done === "object" ? h.done : {},
55	        }));
56	    } catch (err) {
57	      console.warn("Could not read saved habits:", err);
58	      return [];
59	    }
60	  }
61	
62	  function save() {
63	    try {
64	      localStorage.setItem(STORAGE_KEY, JSON.stringify(habits));
65	    } catch (err) {
66	      console.warn("Could not save habits:", err);
67	    }
68	  }
69	
70	  function makeId() {
71	    return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
72	  }
73	
74	  // ---- State ----
75	
76	  let habits = load();
77	  let weekDates = [];
78	  let todayKey = "";
79	
80	  // ---- Rendering ----
81	
82	  function renderHeader() {
83	    headRow.querySelectorAll(".day-head").forEach((th) => th.remove());
84	    const afterDays = headRow.querySelector(".streak-col");
85	
86	    weekDates.forEach((date, i) => {
87	      const th = document.createElement("th");
88	      th.scope = "col";
89	      th.className = "day-head";
90	      const key = toKey(date);
91	      if (key === todayKey) th.classList.add("today");
92	      th.innerHTML = `${DAY_NAMES[i]}<span class="day-date">${date.getDate()}/${date.getMonth() + 1}</span>`;
93	      headRow.insertBefore(th, afterDays);
94	    });
95	
96	    const fmt = { day: "numeric", month: "short" };
97	    const first = weekDates[0].toLocaleDateString(undefined, fmt);
98	    const last = weekDates[6].toLocaleDateString(undefined, { ...fmt, year: "numeric" });
99	    weekLabel.textContent = `Week of ${first} – ${last}`;
100	  }
101	
102	  function renderBody() {
103	    body.innerHTML = "";
104	    const keys = weekDates.map(toKey);
105	
106	    habits.forEach((habit) => {
107	      const tr = document.createElement("tr");
108	      tr.dataset.id = habit.id;
109	
110	      const nameTd = document.createElement("td");
111	      nameTd.className = "habit-name";
112	      nameTd.textContent = habit.name;
113	      tr.appendChild(nameTd);
114	
115	      keys.forEach((key, i) => {
116	        const td = document.createElement("td");
117	        if (key === todayKey) td.classList.add("today");
118	        const cb = document.createElement("input");
119	        cb.type = "checkbox";
120	        cb.className = "day-check";
121	        cb.dataset.date = key;
122	        cb.checked = Boolean(habit.done[key]);
123	        cb.setAttribute("aria-label", `${habit.name} on ${DAY_NAMES[i]} ${key}`);
124	        td.appendChild(cb);
125	        tr.appendChild(td);
126	      });
127	
128	      const streakTd = document.createElement("td");
129	      streakTd.className = "streak-cell";
130	      tr.appendChild(streakTd);
131	
132	      const countTd = document.createElement("td");
133	      countTd.className = "count-cell";
134	      tr.appendChild(countTd);
135	
136	      updateRowStats(tr, habit, keys);
137	
138	      const actionTd = document.createElement("td");
139	      const del = document.createElement("button");
140	      del.type = "button";
141	      del.className = "delete-btn";
142	      del.textContent = "✕";
143	      del.title = "Delete habit";
144	      del.setAttribute("aria-label", `Delete ${habit.name}`);
145	      actionTd.appendChild(del);
146	      tr.appendChild(actionTd);
147	
148	      body.appendChild(tr);
149	    });
150	
151	    const empty = habits.length === 0;
152	    emptyMsg.hidden = !empty;
153	    table.hidden = empty;
154	    renderSummary();
155	  }
156	
157	  // ---- Stats ----
158	
159	  function countWeek(habit, keys) {
160	    return keys.reduce((n, k) => n + (habit.done[k] ? 1 : 0), 0);
161	  }
162	
163	  function percent(part, whole) {
164	    return whole === 0 ? 0 : Math.round((part / whole) * 100);
165	  }
166	
167	  /**
168	   * Consecutive days ticked, counting back from today.
169	   * If today isn't ticked yet the streak isn't broken — it counts back from
170	   * yesterday and `pendingToday` is true (tick today to extend it).
171	   * Days after today never count.
172	   */
173	  function getStreak(habit) {
174	    const now = new Date();
175	    const day = new Date(now.getFullYear(), now.getMonth(), now.getDate());
176	    let pendingToday = false;
177	    if (!habit.done[toKey(day)]) {
178	      pendingToday = true;
179	      day.setDate(day.getDate() - 1);
180	    }
181	    let count = 0;
182	    while (habit.done[toKey(day)]) {
183	      count++;
184	      day.setDate(day.getDate() - 1);
185	    }
186	    return { count, pendingToday: pendingToday && count > 0 };
187	  }
188	
189	  function updateRowStats(tr, habit, keys) {
190	    const { count, pendingToday } = getStreak(habit);
191	    const streakTd = tr.querySelector(".streak-cell");
192	    streakTd.classList.toggle("zero", count === 0);
193	    streakTd.title = pendingToday
194	      ? `${count}-day streak — tick today to keep it going`
195	      : `${count} ${count === 1 ? "day" : "days"} in a row`;
196	    streakTd.innerHTML = count === 0 ? "0" : `🔥 ${count}`;
197	    if (pendingToday) {
198	      const note = document.createElement("span");
199	      note.className = "pending";
200	      note.textContent = "tick today";
201	      streakTd.appendChild(note);
202	    }
203	
204	    const done = countWeek(habit, keys);
205	    const countTd = tr.querySelector(".count-cell");
206	    countTd.innerHTML = "";
207	    countTd.append(`${done}/7`);
208	    const pct = document.createElement("span");
209	    pct.className = "pct";
210	    pct.textContent = `${percent(done, 7)}%`;
211	    countTd.appendChild(pct);
212	  }
213	
