  box-sizing: border-box;
}

:root {
  --bg: #f4f5f7;
  --card: #ffffff;
  --text: #1f2933;
  --muted: #6b7280;
  --border: #e5e7eb;
  --accent: #2f9e6e;
  --accent-dark: #237a55;
  --today: #eaf7f1;
  --danger: #d64545;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.4;
}

.app {
  max-width: 760px;
  margin: 2.5rem auto;
  padding: 1.5rem;
  background: var(--card);
  border-radius: 12px;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.06);
}

header h1 {
  margin: 0;
  font-size: 1.75rem;
}

.week-label {
  margin: 0.25rem 0 1.25rem;
  color: var(--muted);
}

.add-form {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1.25rem;
}

.add-form input {
  flex: 1;
  padding: 0.6rem 0.8rem;
  font-size: 1rem;
  border: 1px solid var(--border);
  border-radius: 8px;
}

.add-form input:focus {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
  border-color: transparent;
}

.add-form button {
  padding: 0.6rem 1.2rem;
  font-size: 1rem;
  font-weight: 600;
  color: #fff;
  background: var(--accent);
  border: none;
  border-radius: 8px;
  cursor: pointer;
}

.add-form button:hover {
  background: var(--accent-dark);
}

.table-wrap {
  overflow-x: auto;
}

.habit-table {
  width: 100%;
  border-collapse: collapse;
}

.habit-table th,
.habit-table td {
  padding: 0.5rem 0.4rem;
  text-align: center;
  border-bottom: 1px solid var(--border);
}

.habit-table th {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--muted);
}

.habit-table .habit-col,
.habit-table .habit-name {
  text-align: left;
  min-width: 140px;
}

.habit-name {
  font-weight: 500;
  word-break: break-word;
}

.day-head .day-date {
  display: block;
  font-weight: 400;
  font-size: 0.75rem;
}

.habit-table .today {
  background: var(--today);
}

.habit-table th.today {
  color: var(--accent-dark);
}

.day-check {
  width: 1.3rem;
  height: 1.3rem;
  accent-color: var(--accent);
  cursor: pointer;
}

.count-col,
.count-cell,
.streak-col,
.streak-cell {
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.count-cell .pct {
  display: block;
  font-size: 0.75rem;
  color: var(--muted);
}

.streak-cell {
  font-weight: 600;
}

.streak-cell.zero {
  color: var(--muted);
  font-weight: 400;
}

.streak-cell .pending {
  display: block;
  font-size: 0.7rem;
  font-weight: 400;
  color: var(--muted);
}

/* ---- Weekly summary ---- */

.summary {
  margin-bottom: 1.25rem;
  padding: 0.9rem 1rem;
  background: var(--bg);
  border-radius: 10px;
}

.summary-text {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 0.5rem;
}

.summary-label {
  font-weight: 600;
}

.summary-pct {
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--accent-dark);
  font-variant-numeric: tabular-nums;
}

.progress {
  height: 10px;
  background: var(--border);
  border-radius: 999px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  width: 0;
  background: var(--accent);
  border-radius: 999px;
  transition: width 0.25s ease;
}

.summary-detail {
  margin: 0.5rem 0 0;
  font-size: 0.85rem;
  color: var(--muted);
}

.delete-btn {
  background: none;
  border: none;
  color: var(--muted);
  font-size: 1.1rem;
  cursor: pointer;
  padding: 0.2rem 0.4rem;
  border-radius: 6px;
}

.delete-btn:hover,
.delete-btn:focus-visible {
  color: var(--danger);
  background: #fdecec;
}

.empty-msg {
  text-align: center;
  color: var(--muted);
  padding: 1.5rem 0 0.5rem;
  margin: 0;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 520px) {
  .app {
    margin: 0;
    border-radius: 0;
    padding: 1rem;
  }
}

