(function () {
  "use strict";

  const STORAGE_KEY = "habitTracker.v1";
  const THEME_KEY = "habitTracker.theme"; // also read by the inline script in index.html
  const DAY_NAMES = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
  const DAYS_IN_WEEK = DAY_NAMES.length;

  const $ = (id) => document.getElementById(id);
  const form = $("add-form");
  const input = $("habit-input");
  const headRow = $("head-row");
  const body = $("habit-body");
  const table = $("habit-table");
  const emptyMsg = $("empty-msg");
  const weekLabel = $("week-label");
  const summary = $("summary");
  const summaryPct = $("summary-pct");
  const summaryBar = $("summary-bar");
  const summaryFill = $("summary-fill");
  const summaryDetail = $("summary-detail");
  const themeToggle = $("theme-toggle");

  // ---- State ----

  let habits = loadHabits();
  let today = null; // local midnight of the current day
  let todayKey = "";
  let weekDates = []; // Mon..Sun of the current week
  let weekKeys = []; // same, as YYYY-MM-DD keys

  // ---- Small helpers ----

  /** Create an element: el("td", { className: "x", dataset: {...}, "aria-label": "..." }, ...children) */
  function el(tag, props = {}, ...children) {
    const node = document.createElement(tag);
    for (const [key, value] of Object.entries(props)) {
      if (key === "dataset") Object.assign(node.dataset, value);
      else if (key.startsWith("aria-")) node.setAttribute(key, value);
      else node[key] = value;
    }
    node.append(...children);
    return node;
  }

  const plural = (n, word) => `${n} ${word}${n === 1 ? "" : "s"}`;
  const percent = (part, whole) => (whole === 0 ? 0 : Math.round((part / whole) * 100));

  // ---- Dates (local time, not UTC) ----

  /** Format a Date as YYYY-MM-DD using local time. */
  function toKey(date) {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, "0");
    const d = String(date.getDate()).padStart(2, "0");
    return `${y}-${m}-${d}`;
  }

  function startOfDay(date) {
    return new Date(date.getFullYear(), date.getMonth(), date.getDate());
  }

  function addDays(date, n) {
    const d = new Date(date);
    d.setDate(d.getDate() + n);
    return d;
  }

  /** The 7 dates (Mon..Sun) of the week containing `day`. */
  function getWeekDates(day) {
    const monday = addDays(day, -((day.getDay() + 6) % 7));
    return DAY_NAMES.map((_, i) => addDays(monday, i));
  }

  // ---- Storage ----

  function loadHabits() {
    try {
      const data = JSON.parse(localStorage.getItem(STORAGE_KEY) || "[]");
      if (!Array.isArray(data)) return [];
      return data
        .filter((h) => h && typeof h.id === "string" && typeof h.name === "string")
        .map((h) => ({
          id: h.id,
          name: h.name,
          done: h.done && typeof h.done === "object" ? h.done : {},
        }));
    } catch (err) {
      console.warn("Could not read saved habits:", err);
      return [];
    }
  }

  function saveHabits() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(habits));
    } catch (err) {
      console.warn("Could not save habits:", err);
    }
  }

  function makeId() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  // ---- Stats ----

  function countWeek(habit) {
    return weekKeys.filter((key) => habit.done[key]).length;
  }

  /**
   * Consecutive days ticked, counting back from today.
   * If today isn't ticked yet the streak isn't broken: it counts back from
   * yesterday and `pendingToday` is true. Days after today never count.
   */
  function getStreak(habit) {
    const pendingToday = !habit.done[todayKey];
    let day = pendingToday ? addDays(today, -1) : today;
    let count = 0;
    while (habit.done[toKey(day)]) {
      count++;
      day = addDays(day, -1);
    }
    return { count, pendingToday: pendingToday && count > 0 };
  }

  // ---- Rendering ----

  function render() {
    today = startOfDay(new Date());
    todayKey = toKey(today);
    weekDates = getWeekDates(today);
    weekKeys = weekDates.map(toKey);
    renderHeader();
    renderHabits();
  }

  function renderHeader() {
    headRow.querySelectorAll(".day-head").forEach((th) => th.remove());
    const afterDays = headRow.querySelector(".streak-col");

    weekDates.forEach((date, i) => {
      const th = el(
        "th",
        { scope: "col", className: weekKeys[i] === todayKey ? "day-head today" : "day-head" },
        DAY_NAMES[i],
        el("span", { className: "day-date" }, `${date.getDate()}/${date.getMonth() + 1}`)
      );
      headRow.insertBefore(th, afterDays);
    });

    const fmt = { day: "numeric", month: "short" };
    const first = weekDates[0].toLocaleDateString(undefined, fmt);
    const last = weekDates[DAYS_IN_WEEK - 1].toLocaleDateString(undefined, { ...fmt, year: "numeric" });
    weekLabel.textContent = `Week of ${first} – ${last}`;
  }

  function renderHabits() {
    body.replaceChildren(...habits.map(buildRow));
    const empty = habits.length === 0;
    emptyMsg.hidden = !empty;
    table.hidden = empty;
    renderSummary();
  }

  function buildRow(habit) {
    const dayCells = weekKeys.map((key, i) =>
      el(
        "td",
        { className: key === todayKey ? "today" : "" },
        el("input", {
          type: "checkbox",
          className: "day-check",
          checked: Boolean(habit.done[key]),
          dataset: { date: key },
          "aria-label": `${habit.name} on ${DAY_NAMES[i]} ${key}`,
        })
      )
    );

    const row = el(
      "tr",
      { dataset: { id: habit.id } },
      el("td", { className: "habit-name" }, habit.name),
      ...dayCells,
      el("td", { className: "streak-cell" }),
      el("td", { className: "count-cell" }),
      el(
        "td",
        {},
        el(
          "button",
          { type: "button", className: "delete-btn", title: "Delete habit", "aria-label": `Delete ${habit.name}` },
          "✕"
        )
      )
    );
    updateRowStats(row, habit);
    return row;
  }

  /** Fill in a row's streak and weekly-count cells. */
  function updateRowStats(row, habit) {
    const { count, pendingToday } = getStreak(habit);
    const streakCell = row.querySelector(".streak-cell");
    streakCell.classList.toggle("zero", count === 0);
    streakCell.title = pendingToday
      ? `${count}-day streak — tick today to keep it going`
      : `${plural(count, "day")} in a row`;
    streakCell.replaceChildren(count === 0 ? "0" : `🔥 ${count}`);
    if (pendingToday) streakCell.append(el("span", { className: "pending" }, "tick today"));

    const done = countWeek(habit);
    row.querySelector(".count-cell").replaceChildren(
      `${done}/${DAYS_IN_WEEK}`,
      el("span", { className: "pct" }, `${percent(done, DAYS_IN_WEEK)}%`)
    );
  }

  /** Overall completion for the week: all ticks across all habits ÷ (habits × 7). */
  function renderSummary() {
    summary.hidden = habits.length === 0;
    if (summary.hidden) return;

    const total = habits.length * DAYS_IN_WEEK;
    const done = habits.reduce((n, h) => n + countWeek(h), 0);
    const pct = percent(done, total);

    summaryPct.textContent = `${pct}%`;
    summaryFill.style.width = `${pct}%`;
    summaryBar.setAttribute("aria-valuenow", String(pct));

    let best = null;
    for (const h of habits) {
      const { count } = getStreak(h);
      if (count > 0 && (!best || count > best.count)) best = { name: h.name, count };
    }

    let detail = `${done} of ${total} check-ins done`;
    if (best) detail += ` · Longest current streak: ${best.name} (${plural(best.count, "day")})`;
    summaryDetail.textContent = detail;
  }

  // ---- Theme ----

  function storedTheme() {
    try {
      const t = localStorage.getItem(THEME_KEY);
      return t === "dark" || t === "light" ? t : null;
    } catch {
      return null;
    }
  }

  const systemDark = window.matchMedia("(prefers-color-scheme: dark)");
  const systemTheme = () => (systemDark.matches ? "dark" : "light");

  /** Apply a theme and update the toggle button, which always offers the *other* theme. */
  function applyTheme(theme) {
    document.documentElement.dataset.theme = theme;
    const next = theme === "dark" ? "light" : "dark";
    themeToggle.textContent = next === "dark" ? "🌙 Dark" : "☀️ Light";
    themeToggle.title = `Switch to ${next} mode`;
    themeToggle.setAttribute("aria-label", `Switch to ${next} mode`);
  }

  themeToggle.addEventListener("click", () => {
    const next = document.documentElement.dataset.theme === "dark" ? "light" : "dark";
    applyTheme(next);
    try {
      localStorage.setItem(THEME_KEY, next);
    } catch (err) {
      console.warn("Could not save theme:", err);
    }
  });

  // Follow the OS setting until the user picks a theme themselves.
  systemDark.addEventListener("change", () => {
    if (!storedTheme()) applyTheme(systemTheme());
  });

  // ---- Habit events ----

  /** The habit whose row contains `node`, if any. */
  function habitFor(node) {
    const id = node.closest("tr")?.dataset.id;
    return habits.find((h) => h.id === id);
  }

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const name = input.value.trim();
    if (!name) return;
    habits.push({ id: makeId(), name, done: {} });
    saveHabits();
    input.value = "";
    renderHabits();
    input.focus();
  });

  body.addEventListener("change", (e) => {
    const box = e.target;
    if (!box.classList.contains("day-check")) return;
    const habit = habitFor(box);
    if (!habit) return;

    if (box.checked) habit.done[box.dataset.date] = true;
    else delete habit.done[box.dataset.date];
    saveHabits();

    // Update just this row (re-rendering would drop keyboard focus from the checkbox).
    updateRowStats(box.closest("tr"), habit);
    renderSummary();
  });

  body.addEventListener("click", (e) => {
    const btn = e.target.closest(".delete-btn");
    const habit = btn && habitFor(btn);
    if (!habit) return;
    if (!confirm(`Delete "${habit.name}"? This removes all its history.`)) return;
    habits = habits.filter((h) => h.id !== habit.id);
    saveHabits();
    renderHabits();
  });

  // ---- Sync across tabs and across midnight ----

  window.addEventListener("storage", (e) => {
    if (e.key === STORAGE_KEY) {
      habits = loadHabits();
      renderHabits();
    } else if (e.key === THEME_KEY) {
      applyTheme(storedTheme() || systemTheme());
    }
  });

  function refreshIfNewDay() {
    if (toKey(new Date()) !== todayKey) render();
  }
  document.addEventListener("visibilitychange", () => {
    if (!document.hidden) refreshIfNewDay();
  });
  setInterval(refreshIfNewDay, 60 * 1000);

  // ---- Start ----

  // The inline script in <head> already set data-theme (avoids a flash of the wrong theme).
  applyTheme(document.documentElement.dataset.theme === "dark" ? "dark" : "light");
  render();
})();

