/* ---- Theme ---- */

:root {
  color-scheme: light;
  --bg: #f4f5f7;
  --card: #ffffff;
  --surface: #f4f5f7; /* summary panel */
  --text: #1f2933;
  --muted: #6b7280;
  --border: #e5e7eb;
  --accent: #2f9e6e; /* checkboxes, progress bar */
  --accent-text: #1f7f56; /* green text */
  --button: #1f7f56; /* white text on this is ~5:1 */
  --button-hover: #186545;
  --today: #eaf7f1;
  --danger: #c53030;
  --danger-bg: #fdecec;
  --shadow: 0 2px 12px rgba(0, 0, 0, 0.06);
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --bg: #0f1215;
  --card: #1a1e23;
  --surface: #23282e;
  --text: #e6e8eb;
  --muted: #9aa3ad;
  --border: #2f353c;
  --accent: #3fb984;
  --accent-text: #6fd3a6;
  --button: #1f7f56;
  --button-hover: #24936a;
  --today: #17302a;
  --danger: #f87171;
  --danger-bg: #3a1f22;
  --shadow: 0 2px 16px rgba(0, 0, 0, 0.5);
}

/* ---- Base ---- */

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.4;
}

button {
  font: inherit;
  cursor: pointer;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

