/* ---- Theme ---- */

:root {
  color-scheme: light;
  --bg: #f4f5f7;
  --card: #ffffff;
  --surface: #f4f5f7; /* summary panel */
  --text: #1f2933;
  --muted: #6b7280;
  --border: #e5e7eb;
  --accent: #2f9e6e; /* checkboxes, progress bar */
  --accent-text: #1f7f56; /* green text */
  --button: #1f7f56; /* white text on this is ~5:1 */
  --button-hover: #186545;
  --today: #eaf7f1;
  --danger: #c53030;
  --danger-bg: #fdecec;
  --shadow: 0 2px 12px rgba(0, 0, 0, 0.06);
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --bg: #0f1215;
  --card: #1a1e23;
  --surface: #23282e;
  --text: #e6e8eb;
  --muted: #9aa3ad;
  --border: #2f353c;
  --accent: #3fb984;
  --accent-text: #6fd3a6;
  --button: #1f7f56;
  --button-hover: #24936a;
  --today: #17302a;
  --danger: #f87171;
  --danger-bg: #3a1f22;
  --shadow: 0 2px 16px rgba(0, 0, 0, 0.5);
}

/* ---- Base ---- */

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.4;
}

button {
  font: inherit;
  cursor: pointer;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ---- Layout ---- */

.app {
  max-width: 760px;
  margin: 2.5rem auto;
  padding: 1.5rem;
  background: var(--card);
  border-radius: 12px;
  box-shadow: var(--shadow);
}

.app-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 1rem;
  margin-bottom: 1.25rem;
}

.app-header h1 {
  margin: 0;
  font-size: 1.75rem;
}

.week-label {
  margin: 0.25rem 0 0;
  color: var(--muted);
}

.theme-toggle {
  flex-shrink: 0;
  padding: 0.4rem 0.8rem;
  font-size: 0.9rem;
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 999px;
}

.theme-toggle:hover {
  border-color: var(--muted);
}

/* ---- Add form ---- */

.add-form {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1.25rem;
}

.add-form input {
  flex: 1;
  min-width: 0;
  padding: 0.6rem 0.8rem;
  font: inherit;
  color: var(--text);
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 8px;
}

.add-form input:focus {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
  border-color: transparent;
}

.add-form button {
  padding: 0.6rem 1.2rem;
  font-weight: 600;
  color: #fff;
  background: var(--button);
  border: none;
  border-radius: 8px;
}

.add-form button:hover {
  background: var(--button-hover);
}

/* ---- Weekly summary ---- */

.summary {
  margin-bottom: 1.25rem;
  padding: 0.9rem 1rem;
  background: var(--surface);
  border-radius: 10px;
}

.summary-text {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 0.5rem;
}

.summary-label {
  font-weight: 600;
}

.summary-pct {
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--accent-text);
  font-variant-numeric: tabular-nums;
}

.progress {
  height: 10px;
  background: var(--border);
  border-radius: 999px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  width: 0;
  background: var(--accent);
  border-radius: 999px;
  transition: width 0.25s ease;
}

.summary-detail {
  margin: 0.5rem 0 0;
  font-size: 0.85rem;
  color: var(--muted);
}

/* ---- Habit table ---- */

.table-wrap {
  overflow-x: auto;
}

.habit-table {
  width: 100%;
  border-collapse: collapse;
}

.habit-table th,
.habit-table td {
  padding: 0.5rem 0.4rem;
  text-align: center;
  border-bottom: 1px solid var(--border);
}

.habit-table th {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--muted);
}

.habit-table .habit-col,
.habit-table .habit-name {
  text-align: left;
  min-width: 140px;
}

.habit-name {
  font-weight: 500;
  word-break: break-word;
}

.day-date {
  display: block;
  font-weight: 400;
  font-size: 0.75rem;
}

.habit-table .today {
  background: var(--today);
}

.habit-table th.today {
  color: var(--accent-text);
}

.day-check {
  width: 1.3rem;
  height: 1.3rem;
  accent-color: var(--accent);
  cursor: pointer;
}

.streak-col,
.streak-cell,
.count-col,
.count-cell {
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.streak-cell {
  font-weight: 600;
}

.streak-cell.zero {
  color: var(--muted);
  font-weight: 400;
}

/* Small grey second line under a number ("tick today", "71%") */
.streak-cell .pending,
.count-cell .pct {
  display: block;
  font-size: 0.75rem;
  font-weight: 400;
  color: var(--muted);
}

.delete-btn {
  padding: 0.2rem 0.4rem;
  font-size: 1.1rem;
  color: var(--muted);
  background: none;
  border: none;
  border-radius: 6px;
}

.delete-btn:hover,
.delete-btn:focus-visible {
  color: var(--danger);
  background: var(--danger-bg);
}

.empty-msg {
  margin: 0;
  padding: 1.5rem 0 0.5rem;
  text-align: center;
  color: var(--muted);
}

/* ---- Small screens ---- */

@media (max-width: 520px) {
  .app {
    margin: 0;
    padding: 1rem;
    border-radius: 0;
  }
}

