assert.deepStrictEqual(JSON.parse(env.store["habitTracker.v1"])[1].done["2026-11-22"], true);

tick(env, 0, "2026-11-19", false);
assert.strictEqual(rowInfo(rowsOf(env)[0]).streak, "🔥 3");
assert.strictEqual(env.ids["summary-detail"].textContent, "10 of 21 check-ins done · Longest current streak: Run (4 days)");

// add a habit
env.ids["habit-input"].value = "  Stretch  ";
env.ids["add-form"].fire("submit", {});
assert.strictEqual(rowsOf(env).length, 4);
assert.strictEqual(rowInfo(rowsOf(env)[3]).name, "Stretch");
assert.strictEqual(env.ids["summary-detail"].textContent.startsWith("10 of 28"), true);

// delete all
while (rowsOf(env).length) env.ids["habit-body"].fire("click", { target: rowsOf(env)[0].querySelector(".delete-btn") });
assert.strictEqual(env.ids.summary.hidden, true);
assert.strictEqual(env.ids["habit-table"].hidden, true);
assert.strictEqual(env.ids["empty-msg"].hidden, false);
assert.strictEqual(env.store["habitTracker.v1"], "[]");
console.log("habits/streaks/percentages: OK");

// ===== Theme =====
const btn = (e) => e.ids["theme-toggle"];

// No saved choice, OS light -> light; button offers dark
env = makeEnv({ osDark: false });
assert.strictEqual(env.themeAfterHead, "light");
assert.strictEqual(btn(env).textContent, "🌙 Dark");
assert.strictEqual(btn(env).attrs["aria-label"], "Switch to dark mode");

// No saved choice, OS dark -> dark (set by head script before app.js)
env = makeEnv({ osDark: true });
assert.strictEqual(env.themeAfterHead, "dark");
assert.strictEqual(btn(env).textContent, "☀️ Light");

// OS change is followed while nothing is saved
env.mq.matches = false; env.mq.listeners.forEach((f) => f());
assert.strictEqual(env.documentElement.dataset.theme, "light");

// Clicking toggles + saves; afterwards OS changes are ignored
btn(env).fire("click", {});
assert.strictEqual(env.documentElement.dataset.theme, "dark");
assert.strictEqual(env.store["habitTracker.theme"], "dark");
btn(env).fire("click", {});
assert.strictEqual(env.documentElement.dataset.theme, "light");
assert.strictEqual(env.store["habitTracker.theme"], "light");
env.mq.matches = true; env.mq.listeners.forEach((f) => f());
assert.strictEqual(env.documentElement.dataset.theme, "light", "saved choice beats OS");

// Saved choice beats OS on load ("remembers the choice")
env = makeEnv({ savedTheme: "dark", osDark: false });
assert.strictEqual(env.themeAfterHead, "dark");
assert.strictEqual(btn(env).textContent, "☀️ Light");
env = makeEnv({ savedTheme: "light", osDark: true });
assert.strictEqual(env.themeAfterHead, "light");

// Garbage saved value falls back to OS
env = makeEnv({ savedTheme: "purple", osDark: true });
assert.strictEqual(env.themeAfterHead, "dark");

// Another tab changes the theme
env = makeEnv({ osDark: false });
env.store["habitTracker.theme"] = "dark";
env.winListeners.storage.forEach((f) => f({ key: "habitTracker.theme" }));
assert.strictEqual(env.documentElement.dataset.theme, "dark");
console.log("theme: OK");

